      recursiveHeart(x1, midY, midX, midY, depth - 1);
      line(midX, midY, midX, y2, x2, y2);
      recursiveHeart(midX, midY, x2, midY, depth - 1);
    }
  };
  recursiveHeart(-50, -50, 50, 50, 4);
}
```

