    public GameObject piecePrefab;

    private GameObject[,] grid;
    private int score;

    void Start()
    {
        grid = new GameObject[gridSizeX, gridSizeY];
        for (int x = 0; x < gridSizeX; x++)
        {
            for (int y = 0; y < gridSizeY; y++)
            {
                grid[x, y] = Instantiate(piecePrefab, new Vector3(x, y, 0), Quaternion.identity);
                grid[x, y].GetComponent<RawImage>().sprite = pieceSprites[Random.Range(0, pieceSprites.Length)];
            }
        }
        score = 0;
    }

    void Update()
    {
        // Detectar si se ha动生成 un match
        CheckForMatch();
    }

    void CheckForMatch()
    {
        // Faltará implementar la lógica para detectar matches
        // Por ahora, solo imprimir un mensaje para verificar
        Debug.Log("Chequeando por matches...");
    }

    public void RestartGame()
    {
        // Reinitizar el juego
        score = 0;
        grid = new GameObject[gridSizeX, gridSizeY];
        for (int x = 0; x < gridSizeX; x++)
        {
            for (int y = 0; y < gridSizeY; y++)
            {
                grid[x, y] = Instantiate(piecePrefab, new Vector3(x, y, 0), Quaternion.identity);
                grid[x, y].GetComponent<RawImage>().sprite = pieceSprites[Random.Range(0, pieceSprites.Length)];
            }
        }
    }
}
```
