#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/gpio.h>

#define GPIO_PIN 17

int main() {
    int fd;
    int val;

    // Open GPIO pin 17 for output
    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        perror("export");
        exit(1);
    }
    write(fd, &GPIO_PIN, sizeof(GPIO_PIN));
    close(fd);

    // Set GPIO pin 17 as an output
    fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (fd == -1) {
        perror("direction");
        exit(1);
    }
    write(fd, "out", 3);
    close(fd);

    // Blink the LED
    while (1) {
        // Set GPIO pin 17 high (LED on)
        fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
        if (fd == -1) {
            perror("value");
            exit(1);
        }
        write(fd, "1", 1);
        close(fd);
        usleep(500000); // 0.5 seconds

        // Set GPIO pin 17 low (LED off)
        fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
        if (fd == -1) {
            perror("value");
            exit(1);
        }
        write(fd, "0", 1);
        close(fd);
        usleep(500000); // 0.5 seconds
    }

    return 0;
}
```
