    double hzh = dhz(i);
    double hhh = h(i);
    double ph = p(i);

    // Compute the derivative in z-direction
    double dhzh = (h[i + 1] - h[i - 1]) / (2 * dz);

    // Compute the integral term
    double integral = (M(zh, hhh) * dhzh) / (alpha * zh + hhh) + (p0 - ph) / (alpha * zh + hhh);

    // Update the pressure
    p(i) = ph + dt * integral;

    // Update the height
    h(i) = hhh + dt * (-1 / (alpha * zh + hhh) * dhzh);
  }
