```
class PasswordManager {
  constructor() {
    this.passphrases = {}; // almacenamiento de contraseñas
  }

  // función para crear una contraseña
  createPassword(password, username) {
    const passphrase = this.generatePassphrase(password, username);
    this.passphrases[username] = passphrase;
    return passphrase;
  }

  // función para generar una passphrase (contraseña fuerte)
  generatePassphrase(password, username) {
    const salt = this.getSalt();
    const hashedPassword = this.hashPassword(password, salt);
    return `${username}:${hashedPassword}:${salt}`;
  }

  // función para obtener el salt (un valor aleatorio y único para cada contraseña)
  getSalt() {
    return `${Date.now()}:${Math.floor(Math.random() * 1000000)}`;
  }

  // función para hashing (encriptar) la contraseña
  hashPassword(password, salt) {
    const crypto = window.crypto || window.msCrypto;
    const hash = crypto.subtle.digest('SHA-256', new TextEncoder().encode(`${password}${salt}`));
    return crypto.subtle.digest('base64', hash);
  }

  // función para verificar la contraseña
  verifyPassword(username, password, passphrase) {
    const storedPassphrase = this.passphrases[username];
    if (!storedPassphrase) return false;
    const [storedUsername, storedHashedPassword, storedSalt] = storedPassphrase.split(':');
    if (storedUsername !== username) return false;
    const hashedPassword = this.hashPassword(password, storedSalt);
    return hashedPassword === storedHashedPassword;
  }
}
