#define RECTANGLE_METHOD eps = 0.001;
#define TRAPEZOID_METHOD eps = 0.001;
#define SIMPSON_METHOD eps = 0.001;

double calc_rect(int num_threads, int num_segments) {
    double result = 0;
    for (int i = 0; i < num_segments; i++) {
        double x = (i * num_segments * 1.0) / (num_threads - 1);
        result += INTEGRAL_FUNC(x) * (num_segments * 1.0 / (num_threads - 1));
    }
    return result;
}

double calc_trapezoid(int num_threads, int num_segments) {
    double result = 0;
    for (int i = 0; i < num_segments; i++) {
        double x = (i * num_segments * 1.0) / (num_threads - 1);
        result += 0.5 * (INTEGRAL_FUNC(x) + INTEGRAL_FUNC((x + 1.0 * num_segments / (num_threads - 1))));
    }
    return result;
}

double calc_simpson(int num_threads, int num_segments) {
    double result = 0;
    for (int i = 0; i < num_segments; i++) {
        double x = (i * num_segments * 1.0) / (num_threads - 1);
        result += INTEGRAL_FUNC(x) * (num_segments * 1.0 / (num_threads - 1));
    }
    for (int i = 0; i < num_segments; i++) {
        if (i % 2 == 1) {
            result += 4 * INTEGRAL_FUNC((i * num_segments * 1.0) / (num_threads - 1));
        }
    }
    return result;
}

