    double result;

    Randomize();
    Sleep(rand() % 100);

    switch (rand() % 3) {
    case 0:
        result = calc_rect((int)pParam, num_segments);
        break;
    case 1:
        result = calc_trapezoid((int)pParam, num_segments);
        break;
    case 2:
        result = calc_simpson((int)pParam, num_segments);
        break;
    }

    EnterCriticalSection(&cs);
    ReleaseSemaphore(sem, 1);
    printf("Result: %lf\n", result);
    LeaveCriticalSection(&cs);

    return 0;
}

int main() {
    HANDLE threads[NTHREADS];
    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);
    HANDLE semaphore_hand = CreateSemaphore(NULL, 0, NTHREADS, NULL);

    InitializeCriticalSection(&cs);

    DWORD thread_id;
    for (int i = 0; i < NTHREADS; i++) {
        threads[i] = CreateThread(NULL, 0, threadProc, (LPVOID)(i), 0, &thread_id);
    }

    for (int i = 0; i < NTHREADS; i++) {
        WaitForSingleObject(semaphore_hand, INFINITE);
    }

    for (int i = 0; i < NTHREADS; i++) {
        CloseHandle(threads[i]);
    }

    CloseHandle(mutex);
    CloseHandle(semaphore_hand);

    DeleteCriticalSection(&cs);

    return 0;
}
