```
import React, { Component } from 'react';
import { GoogleLogin } from 'react-google-login';
import { Typography, Button, Snackbar } from '@material-ui/core';
import axios from 'axios';

class GoogleOAuth extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isLoggedIn: false,
      username: '',
      accessToken: '',
      refreshToken: '',
      error: null,
    };
  }

  handleLogin = (googleUser) => {
    const { accessToken, refreshToken } = googleUser;
    this.setState({
      isLoggedIn: true,
      accessToken,
      refreshToken,
    });

    // Store the access token and refresh token in local storage
    localStorage.setItem('accessToken', accessToken);
    localStorage.setItem('refreshToken', refreshToken);

    // Make a request to your server to get the user's profile information
    axios.get('/api/user', {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    })
    .then((response) => {
      this.setState({ username: response.data.username });
    })
    .catch((error) => {
      this.setState({ error: error.message });
    });
  }

  handleLogout = () => {
    this.setState({
      isLoggedIn: false,
      username: '',
      accessToken: '',
      refreshToken: '',
    });

    // Remove the access token and refresh token from local storage
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
  }

  render() {
    const { isLoggedIn, username, error } = this.state;
    const clientId = 'YOUR_CLIENT_ID';
    const redirectUri = 'YOUR_REDIRECT_URI';

    return (
      <div>
        {isLoggedIn ? (
          <div>
            <Typography variant="h5">Welcome, {username}!</Typography>
            <Button onClick={this.handleLogout}>Logout</Button>
          </div>
        ) : (
          <GoogleLogin
            clientId={clientId}
            redirectUri={redirectUri}
            scope="profile email"
            buttonText="Login with Google"
            onSuccess={this.handleLogin}
            onFailure={(error) => {
              this.setState({ error: error.error.message });
            }}
          />
        )}
        {error && (
          <Snackbar
            message={error}
            onClose={() => this.setState({ error: null })}
          />
        )}
      </div>
    );
  }
}

export default GoogleOAuth;
```
